:root{
 --red:#AE1E26; --red-deep:#8a161b; --red-soft:#c33138;
 --ink:#1a1512; --ink-2:#231c17; --steel:#39352f;
 --paper:#ffffff; --paper-2:#faf8f5; --line:#e7e0d6;
 --tx:#1f1915; --mut:#6f665b;
 --gut:clamp(18px,4.4vw,56px); --max:1360px; --r:12px;
 --serif:'Cormorant Garamond',Georgia,serif; --sans:'Inter',system-ui,sans-serif;
}
*{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;font-family:var(--sans);color:var(--tx);background:var(--paper);line-height:1.6;overflow-wrap:break-word;min-height:100svh;display:flex;flex-direction:column}
main{flex:1 0 auto}
svg{width:18px;height:18px;flex-shrink:0}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
h1,h2,h3{font-family:var(--serif);font-weight:600;line-height:1.02;margin:0}
.wrap{max-width:var(--max);margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.skip{position:absolute;left:-999px;top:0;background:var(--red);color:#fff;padding:10px 16px;z-index:200}
.skip:focus{left:12px;top:12px}
.eyebrow{font-family:var(--sans);font-weight:600;font-size:.76rem;letter-spacing:.3em;text-transform:uppercase;color:var(--red)}

@keyframes rvIn{from{opacity:0;transform:translateY(30px)}to{opacity:1;transform:none}}
@keyframes lineGrow{from{transform:scaleX(0)}to{transform:scaleX(1)}}
@keyframes barGrow{from{transform:scaleY(0)}to{transform:scaleY(1)}}
.rv{animation:rvIn .95s cubic-bezier(.2,.7,.2,1) both;animation-delay:var(--d,0s)}
@media (prefers-reduced-motion:reduce){*{animation-duration:.001s!important}}

/* top red strip */
.strip{background:var(--red);color:#fff;text-align:center;font-size:.72rem;font-weight:600;letter-spacing:.26em;text-transform:uppercase;padding:9px 16px}

/* HEADER */
header{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.92);backdrop-filter:blur(12px);border-bottom:1px solid var(--line)}
.hdr-in{display:flex;align-items:center;gap:22px;min-height:76px}
.logo{display:flex;align-items:center;gap:13px;margin-right:auto}
.logo-img{height:42px;width:auto;display:block}
.emb{width:44px;height:44px;border-radius:11px;box-shadow:0 5px 16px rgba(174,30,38,.26)}
.logo-wm{font-family:var(--serif);font-weight:700;font-size:1.72rem;letter-spacing:.2em;color:var(--ink);line-height:1}
.nav{display:flex;align-items:center;gap:36px}
.navlink{color:var(--ink);font-weight:600;font-size:.76rem;letter-spacing:.17em;text-transform:uppercase;position:relative;padding:6px 0}
.navlink::after{content:"";position:absolute;left:0;right:100%;bottom:0;height:1.5px;background:var(--red);transition:right .28s}
.navlink:hover::after{right:0}
.round{display:inline-flex;align-items:center;justify-content:center;width:46px;height:46px;border-radius:50%;border:1.5px solid var(--red);color:var(--red);transition:.3s}
.round svg{width:18px;height:18px;transition:transform .3s}
.round:hover{background:var(--red);color:#fff} .round:hover svg{transform:translateX(3px)}
.navt{display:none}
.burger{display:none;flex-direction:column;gap:5px;width:46px;height:40px;align-items:center;justify-content:center;cursor:pointer;border:1px solid var(--line);border-radius:8px}
.burger span{width:22px;height:2px;background:var(--ink);border-radius:2px;transition:.25s}
@media(max-width:880px){
 .burger{display:flex}
 .nav{position:fixed;top:0;right:0;height:100vh;width:min(84vw,320px);background:var(--paper);flex-direction:column;align-items:stretch;gap:2px;padding:96px 28px 30px;clip-path:inset(0 0 0 100%);pointer-events:none;transition:clip-path .35s ease;box-shadow:-20px 0 60px rgba(0,0,0,.14);border-left:1px solid var(--line)}
 .navt:checked ~ .nav{clip-path:inset(0);pointer-events:auto}
 .navlink{padding:15px 2px;border-bottom:1px solid var(--line);font-size:.84rem} .navlink::after{display:none}
 .nav .round{margin-top:16px;align-self:flex-start}
 .navt:checked ~ .burger span:nth-child(1){transform:translateY(7px) rotate(45deg)}
 .navt:checked ~ .burger span:nth-child(2){opacity:0}
 .navt:checked ~ .burger span:nth-child(3){transform:translateY(-7px) rotate(-45deg)}
}

/* HERO */
.hero{position:relative;overflow:hidden;background:var(--paper)}
.hero-redbar{position:absolute;right:0;top:0;height:100%;width:clamp(12px,2vw,28px);background:var(--red);transform-origin:top;animation:barGrow .9s .25s both;z-index:1}
.hero-in{position:relative;z-index:2;padding-top:clamp(40px,6vw,74px);padding-bottom:clamp(30px,4vw,48px)}
.hero-head{max-width:900px}
.hero h1{font-size:clamp(2.5rem,5.2vw,4.7rem);color:var(--ink);font-weight:600;margin:.12em 0 0;letter-spacing:.002em;line-height:1}
.lead{display:flex;align-items:center;gap:20px;margin-top:22px;max-width:760px}
.lead::before{content:"";width:clamp(28px,4vw,52px);height:2px;background:var(--red);flex-shrink:0;transform-origin:left;animation:lineGrow .9s .4s both}
.lead span{font-family:var(--serif);font-size:clamp(1.1rem,2.1vw,1.5rem);color:var(--ink);font-weight:500}

/* EXPLORE label row */
.explore-row{display:flex;align-items:center;gap:20px;padding-top:clamp(14px,2.4vw,26px);padding-bottom:clamp(14px,2vw,22px)}
.explore-row .lbl{display:inline-flex;align-items:baseline;gap:14px;white-space:nowrap}
.explore-row .lbl .eyebrow{color:var(--ink)}
.explore-row .lbl .num{font-family:var(--sans);font-weight:600;font-size:.76rem;letter-spacing:.18em;color:var(--red)}
.explore-row .bar{height:1.5px;background:var(--ink);flex:1;transform-origin:left;animation:lineGrow 1s .3s both}

/* BENTO */
#brands{padding-left:max(var(--gut),calc((100% - var(--max))/2));padding-right:max(var(--gut),calc((100% - var(--max))/2))}
.bento{display:grid;grid-template-columns:1.22fr 1fr 1fr;gap:14px}
.bento>*{min-width:0}
.btile{position:relative;overflow:hidden;border-radius:var(--r);display:block;background:#0e1b2e;isolation:isolate}
.b-stone{grid-column:1;grid-row:1 / span 2}
.b-living{grid-column:2 / span 2;grid-row:1;aspect-ratio:2.34/1}
.b-kitchens{grid-column:2;grid-row:2;aspect-ratio:1.27/1}
.b-home{grid-column:3;grid-row:2;aspect-ratio:1.27/1}
.tmedia{position:absolute;inset:0;overflow:hidden}
.tmedia .ph-img{width:100%;height:100%;object-fit:cover;transition:transform .7s cubic-bezier(.2,.7,.2,1)}
.btile:hover .tmedia .ph-img{transform:scale(1.06)}
.scrim{position:absolute;inset:0;z-index:2;background:linear-gradient(to top,rgba(18,14,11,.82),rgba(18,14,11,.25) 44%,rgba(18,14,11,0) 68%);transition:background .45s}
.btile:hover .scrim{background:linear-gradient(to top,rgba(138,22,27,.62),rgba(18,14,11,.4) 48%,rgba(18,14,11,.05) 74%)}
.tile-cap{position:absolute;left:0;bottom:0;z-index:3;padding:clamp(20px,2.2vw,34px);width:100%}
.tile-cap h3{color:#fff;text-transform:uppercase;letter-spacing:.04em;font-weight:600;font-size:clamp(1.4rem,2.3vw,2.3rem);text-shadow:0 2px 22px rgba(0,0,0,.45)}
.b-stone .tile-cap h3{font-size:clamp(1.7rem,3vw,3.1rem)}
.explore{display:inline-flex;align-items:center;gap:15px;margin-top:13px;color:#fff;font-size:.7rem;letter-spacing:.22em;text-transform:uppercase;font-weight:600;font-family:var(--sans)}
.rbtn{display:inline-flex;align-items:center;justify-content:center;width:42px;height:42px;border-radius:50%;border:1.5px solid rgba(255,255,255,.8);color:#fff;transition:.35s}
.rbtn svg{width:16px;height:16px;transition:transform .35s}
.btile:hover .rbtn{background:var(--red);border-color:var(--red);transform:scale(1.08)}
.btile:hover .rbtn svg{transform:translateX(3px)}

/* STEEL bar */
.steel-wrap{padding-top:14px;padding-bottom:clamp(30px,5vw,64px)}
.explore-row{margin-top:0}
.b-steel{position:relative;display:block;border-radius:var(--r);overflow:hidden;aspect-ratio:7.4/1;background:var(--ink)}
.b-steel .tmedia{position:absolute;inset:0;overflow:hidden}
.b-steel .tmedia .ph-img{width:100%;height:100%;object-fit:cover;filter:grayscale(.6) contrast(1.03) brightness(.82)}
.b-steel .scrim{position:absolute;inset:0;z-index:2;background:linear-gradient(90deg,rgba(24,19,15,.92),rgba(24,19,15,.55) 52%,rgba(24,19,15,.35))}
.steel-cap{position:absolute;inset:0;z-index:3;display:flex;align-items:center;gap:24px;padding:0 clamp(22px,3vw,44px)}
.steel-cap h3{color:#fff;text-transform:uppercase;letter-spacing:.05em;font-size:clamp(1.4rem,2.7vw,2.4rem)}
.soon-pill{display:inline-flex;align-items:center;border:1.5px solid rgba(255,255,255,.55);color:#fff;font-family:var(--sans);font-size:.64rem;font-weight:600;letter-spacing:.2em;text-transform:uppercase;padding:9px 17px;border-radius:3px}
@media(max-width:900px){
 .bento{grid-template-columns:1fr 1fr}
 .b-stone,.b-living,.b-kitchens,.b-home{grid-column:auto;grid-row:auto;aspect-ratio:1.25/1}
 .b-living{grid-column:1 / -1;aspect-ratio:2/1}
 .b-steel{aspect-ratio:5/1}
}
@media(max-width:540px){
 .bento{grid-template-columns:1fr}
 .b-stone,.b-living,.b-kitchens,.b-home{aspect-ratio:1.35/1}
 .b-steel{aspect-ratio:3.2/1}
 .steel-cap{flex-direction:column;align-items:flex-start;justify-content:center;gap:12px}
}

/* FOOTER */
footer{background:var(--paper);border-top:1px solid var(--line)}
.foot-rule{display:flex;align-items:center;gap:clamp(20px,4vw,40px);padding-top:clamp(34px,5vw,56px);padding-bottom:clamp(18px,3vw,30px)}
.foot-rule .fl{flex:1;height:1px;background:var(--red)}
.foot-wm{font-family:var(--serif);font-weight:700;font-size:clamp(1.5rem,3vw,2.1rem);letter-spacing:.34em;color:var(--ink);padding-left:.34em}
.foot-bot-in{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;padding-bottom:30px;font-size:.8rem;color:var(--mut)}
.foot-nav{display:flex;gap:22px;flex-wrap:wrap}
.foot-nav a{font-size:.72rem;letter-spacing:.12em;text-transform:uppercase;color:var(--mut)} .foot-nav a:hover{color:var(--red)}
.built{display:inline-flex;align-items:center;gap:9px;color:var(--mut)}
.built-ico{width:24px;height:24px;border-radius:7px} .built b{color:var(--red);font-weight:700}

